-- Migration: Year 4 - Ethics, Law & Health Systems (PART 3: 101-150)
-- Date: 2026-05-16
-- Target: US MD / MBBS / USMLE Step 3 Level
-- Topic: Healthcare systems — Medicaid & CHIP

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Fetch the topic_id dynamically via slug
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-healthcare-systems' LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic with slug "ethics-healthcare-systems" not found.';
    END IF;

    -- SECTION: MEDICAID BASICS & ELIGIBILITY
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Medicaid is best described as which of the following types of programs?', '["Social insurance (like Social Security)", "A means-tested social welfare program", "A private-public partnership", "An employer-mandated benefit"]', 1, 'Medicaid is means-tested, meaning eligibility is based on having low income and limited resources.'),
    (v_topic_id, 'Which of the following describes the funding structure of the Medicaid program?', '["100% federal funding", "100% state funding", "Joint federal and state funding", "Private donations and state taxes"]', 2, 'Medicaid is a joint program where the federal government matches state spending.'),
    (v_topic_id, 'The percentage of Medicaid costs paid by the federal government to a state is known as the:', '["FICA", "FMAP (Federal Medical Assistance Percentage)", "COBRA", "DRG"]', 1, 'FMAP varies by state based on the state''s per capita income; poorer states receive a higher federal match.'),
    (v_topic_id, 'By law, the minimum FMAP (federal match) that any state can receive is:', '["25%", "50%", "75%", "90%"]', 1, 'The federal government pays at least 50% of Medicaid costs in every state.'),
    (v_topic_id, 'Which of the following entities is responsible for determining the specific eligibility rules and administering the day-to-day operations of Medicaid?', '["The CMS", "The individual states", "The Social Security Administration", "Local county hospitals"]', 1, 'Within broad federal guidelines, each state operates its own Medicaid program.'),
    (v_topic_id, 'Under the Affordable Care Act (ACA), states were given the option to expand Medicaid to cover almost all non-elderly adults with incomes up to what percentage of the Federal Poverty Level (FPL)?', '["100% FPL", "133% FPL (effectively 138% with a 5% income disregard)", "200% FPL", "250% FPL"]', 1, 'The ACA expansion targeted adults up to 138% of the FPL.'),
    (v_topic_id, 'Which of the following best describes the "Categorically Needy" group in Medicaid?', '["People with very high medical bills", "Groups that states MUST cover to receive federal funds (e.g., low-income children, pregnant women, SSI recipients)", "Individuals who are homeless", "Anyone who doesn''t have a job"]', 1, 'Categorically needy groups are the mandatory populations defined by federal law.'),
    (v_topic_id, 'The "Medically Needy" (or "Spend-down") program allows individuals to qualify for Medicaid if:', '["They are over age 85", "Their medical expenses reduce their net income below the state''s eligibility threshold", "They live in a rural area", "They have a terminal illness"]', 1, 'This allows people with higher incomes but catastrophic medical costs to qualify.'),
    (v_topic_id, 'If a state chooses to participate in Medicaid, which of the following is a MANDATORY benefit they must provide?', '["Inpatient and outpatient hospital services", "Prescription drugs", "Adult dental care", "Physical therapy"]', 0, 'Hospital services are mandatory; prescription drugs and adult dental are actually "optional" benefits, though almost all states cover drugs.'),
    (v_topic_id, 'The EPSDT (Early and Periodic Screening, Diagnostic, and Treatment) benefit is a mandatory Medicaid service for which population?', '["Seniors in nursing homes", "Children under age 21", "Pregnant women only", "Patients with ESRD"]', 1, 'EPSDT ensures that children receive comprehensive preventive and medically necessary care.'),

    -- SECTION: MEDICAID & LONG-TERM CARE
    (v_topic_id, 'Which program is the largest single payer for long-term nursing home care in the United States?', '["Medicare", "Medicaid", "Private Long-term Care Insurance", "Social Security"]', 1, 'Medicaid covers more than 60% of all nursing home residents because Medicare only covers short-term rehab.'),
    (v_topic_id, 'To qualify for Medicaid coverage of long-term nursing home care, an individual must meet which of the following financial criteria?', '["Income limits only", "Asset (resource) limits only", "Both strict income and asset limits", "No financial limits if they are over 85"]', 2, 'Long-term care Medicaid has stringent limits on both monthly income and "countable" assets (e.g., $2,000 for an individual).'),
    (v_topic_id, 'Which of the following is typically considered an "EXEMPT" asset when determining Medicaid eligibility for nursing home care?', '["The patient''s primary residence (up to a certain equity value)", "A second vacation home", "Stock portfolios", "Cash in a savings account"]', 0, 'A primary home, one car, and personal belongings are usually exempt from asset calculations.'),
    (v_topic_id, 'Medicaid has a "Look-back Period" to check for assets that were given away or sold for less than fair market value. How long is this period in most states?', '["12 months", "24 months", "36 months", "60 months (5 years)"]', 3, 'States look back 5 years to prevent people from "impoverishing" themselves to qualify for Medicaid.'),
    (v_topic_id, 'What happens if an individual is found to have transferred assets for less than fair market value during the look-back period?', '["They are permanently banned from Medicaid", "A "penalty period" of ineligibility is calculated based on the value of the transfer", "Nothing, if the gift was to a child", "They must pay a $5,000 fine"]', 1, 'The penalty period is roughly the value of the gift divided by the average monthly cost of nursing home care in that state.'),
    (v_topic_id, 'The "Spousal Impoverishment" rules in Medicaid are designed to:', '["Make sure both spouses go into the nursing home", "Allow the spouse living at home (community spouse) to keep a certain amount of income and assets", "Require the community spouse to sell the family home", "Prevent the community spouse from working"]', 1, 'These rules protect the spouse still living in the community from becoming destitute when the other spouse enters a nursing home.'),
    (v_topic_id, 'What is the "Estate Recovery" program in Medicaid?', '["A program to help people buy homes", "The requirement for states to attempt to recover the costs of long-term care from the deceased beneficiary''s estate", "A way to donate land to the government", "None of the above"]', 1, 'Federal law requires states to seek repayment from the estates of deceased Medicaid beneficiaries who received long-term care after age 55.'),

    -- SECTION: DUAL ELIGIBILITY & QMB/SLMB
    (v_topic_id, 'A "Dual Eligible" individual is someone who:', '["Is eligible for both Medicare and Medicaid", "Has two different Medicare Advantage plans", "Is covered by both an employer and a private plan", "Is eligible for Medicare in two different states"]', 0, 'Dual eligibles are often the most vulnerable and medically complex patients.'),
    (v_topic_id, 'For a dual eligible patient, which program is the "Primary Payer" for services covered by both (e.g., a hospital stay)?', '["Medicaid", "Medicare", "They split 50/50", "The patient chooses"]', 1, 'Medicare always pays first for covered services; Medicaid is the "payer of last resort."'),
    (v_topic_id, 'The "Qualified Medicare Beneficiary" (QMB) program is a Medicaid-funded program that:', '["Provides extra food stamps", "Pays for Medicare Part A and B premiums, deductibles, and coinsurance", "Is only for disabled children", "Replaces Medicare entirely"]', 1, 'QMB is the most comprehensive "Medicare Savings Program" for low-income seniors.'),
    (v_topic_id, 'The SLMB (Specified Low-Income Medicare Beneficiary) program differs from QMB in that it:', '["Only pays the Medicare Part B premium", "Pays for all hospital costs", "Is only for those over 90", "Requires the patient to be in a nursing home"]', 0, 'SLMB has slightly higher income limits than QMB but only covers the Part B premium.'),
    (v_topic_id, 'Which program provides prescription drug coverage for dual eligible individuals?', '["Medicaid", "Medicare Part D (via the Low-Income Subsidy)", "Medicare Part B", "A state-run drug pool"]', 1, 'Since 2006, drug coverage for dual eligibles was moved from Medicaid to Medicare Part D.'),

    -- SECTION: CHIP (CHILDREN''S HEALTH INSURANCE PROGRAM)
    (v_topic_id, 'CHIP was created to provide health insurance to which group of people?', '["Children in families with incomes too high for Medicaid but too low to afford private insurance", "Children with severe disabilities only", "Immigrant children only", "All children regardless of income"]', 0, 'CHIP "fills the gap" for families who earn too much for Medicaid but cannot afford private coverage.'),
    (v_topic_id, 'Which of the following is true regarding CHIP funding?', '["It is 100% state-funded", "It is a joint federal-state program, similar to Medicaid but with a higher federal match (Enhanced FMAP)", "It is funded by a tax on toys", "It is only funded through private donations"]', 1, 'The federal government pays a significantly higher percentage of CHIP costs than Medicaid costs (often 15-23% higher).'),
    (v_topic_id, 'States can implement CHIP in which of the following ways?', '["As an expansion of their Medicaid program", "As a separate stand-alone program", "As a combination of both", "All of the above"]', 3, 'States have flexibility in how they structure their CHIP programs.'),
    (v_topic_id, 'Unlike Medicaid, CHIP is NOT an "entitlement" program. What does this mean?', '["States can cap enrollment or have waiting lists if they run out of funds", "The program is only for adults", "People have to pay to join", "It only lasts for one year"]', 0, 'As a block-granted program, CHIP funding is limited, whereas Medicaid must cover everyone who meets eligibility rules regardless of cost.'),
    (v_topic_id, 'Does CHIP ever cover adults?', '["No, never", "Only pregnant women in some states", "Only the parents of the children", "Only if the adult is disabled"]', 1, 'States can use CHIP funds to cover pregnant women, but it is primarily for children.'),

    -- SECTION: MEDICAID MANAGED CARE & POLICY
    (v_topic_id, 'What is "Medicaid Managed Care"?', '["A system where the state pays doctors directly for every service", "A system where the state pays a private health plan a fixed monthly fee (capitation) to provide all care for a member", "A way for patients to manage their own bills", "A program only for dental care"]', 1, 'Most Medicaid beneficiaries are now enrolled in private managed care plans rather than traditional fee-for-service.'),
    (v_topic_id, 'In the context of Medicaid, "Capitation" refers to:', '["A limit on the number of patients", "A fixed per-member per-month payment to a health plan", "The process of billing the federal government", "The state capital''s healthcare budget"]', 1, 'Capitation shifts financial risk from the state to the managed care organization.'),
    (v_topic_id, 'What is a "Medicaid Waiver" (e.g., Section 1115 Waiver)?', '["An exemption from paying taxes", "Permission from the federal government for a state to test new ways of delivering or paying for Medicaid services", "A document allowing a patient to skip a doctor visit", "A waiver of the age requirement for Medicare"]', 1, 'Waivers allow states to experiment with things like work requirements, different delivery models, or expanded benefits.'),
    (v_topic_id, 'The "Payer of Last Resort" rule means that:', '["Medicaid only pays if the patient has no money", "Medicaid only pays after all other insurance (e.g., Medicare, private, auto insurance) has paid", "The hospital is the last place to get paid", "The government pays everyone last"]', 1, 'If a patient has any other insurance, that insurance must pay before Medicaid.'),
    (v_topic_id, 'What is "Crowd-out" in the context of Medicaid and CHIP?', '["When too many people are in a waiting room", "When the availability of public insurance causes people to drop their private insurance", "When the government takes over all hospitals", "A type of insurance fraud"]', 1, 'Policy makers try to design programs to minimize crowd-out and target those who truly lack access to private plans.'),

    -- SECTION: ADDITIONAL MEDICAID/CHIP DETAILS
    (v_topic_id, 'Which of the following is an "Optional" benefit that many states choose to provide under Medicaid?', '["Physical therapy", "Family planning services", "X-ray services", "Physician services"]', 0, 'Physical therapy, occupational therapy, and speech therapy are optional benefits.'),
    (v_topic_id, 'Are states allowed to charge "Premiums" to Medicaid beneficiaries?', '["Yes, for everyone", "No, except for certain groups with higher incomes (e.g., those in the medically needy group)", "Only for children", "Only for emergency care"]', 1, 'Premiums are generally prohibited for the lowest-income Medicaid beneficiaries.'),
    (v_topic_id, 'What is the "Home and Community-Based Services" (HCBS) waiver (Section 1915c)?', '["A waiver to allow people to live in nursing homes", "A program that allows Medicaid to pay for services that help people stay in their homes instead of an institution", "A way to get free home repairs", "A waiver for property taxes"]', 1, 'HCBS waivers are a key part of the "rebalancing" effort to move long-term care out of institutions.'),
    (v_topic_id, 'A "Qualified Pregnant Woman" for Medicaid purposes:', '["Must be married", "Is eligible based on income alone, regardless of whether she meets other categorical requirements", "Only gets coverage for the delivery", "Must have other children already"]', 1, 'Pregnancy is a major eligibility pathway for Medicaid.'),
    (v_topic_id, 'Medicaid coverage for a pregnant woman typically continues for how long after the birth of the child?', '["60 days", "6 months", "12 months (in many expansion states)", "Indefinitely"]', 2, 'The standard was 60 days, but the American Rescue Plan Act allowed states to extend postpartum coverage to 12 months, which many have adopted.'),
    (v_topic_id, 'The "Presumptive Eligibility" rule in Medicaid allows:', '["Patients to assume they are covered", "Hospitals and clinics to immediately enroll patients who appear eligible, providing temporary coverage while the full application is processed", "The government to presume everyone is poor", "None of the above"]', 1, 'This is often used for pregnant women or children to ensure they get immediate care.'),
    (v_topic_id, 'What is "Retroactive Eligibility" in Medicaid?', '["Coverage that starts the year before you apply", "Medicaid paying for medical bills incurred up to 3 months BEFORE the month of application, if the person was eligible at that time", "A way to get a refund for private insurance", "Coverage for elderly people only"]', 1, 'Retroactive coverage is a critical safety net for people who have an emergency before they can apply for Medicaid.'),
    (v_topic_id, 'In states that did NOT expand Medicaid under the ACA, who typically falls into the "Coverage Gap"?', '["Rich people", "Adults whose income is too high for traditional Medicaid but too low to qualify for ACA marketplace subsidies", "Children in CHIP", "Seniors on Medicare"]', 1, 'Marketplace subsidies start at 100% FPL. In non-expansion states, Medicaid for adults may end at 40% FPL, leaving those in between with no options.'),
    (v_topic_id, 'Which of the following is true about "Immigrant Eligibility" for Medicaid?', '["All immigrants are eligible immediately", "Most "qualified" immigrants (e.g., green card holders) must wait 5 years before they can enroll in Medicaid", "Undocumented immigrants are eligible for full Medicaid", "There are no residency requirements"]', 1, 'The "5-year bar" is a federal rule for most legal immigrants, though some states use their own funds to cover people sooner.'),
    (v_topic_id, 'What is "Emergency Medicaid"?', '["A program for paramedics", "Federal funding that pays for emergency services (e.g., labor and delivery, stabilization) for individuals who meet all Medicaid criteria EXCEPT citizenship status", "A type of private insurance", "A program that only works on weekends"]', 1, 'Emergency Medicaid is the only federal Medicaid funding available for undocumented individuals.'),
    (v_topic_id, 'Which of the following is an example of "Mandatory" Medicaid coverage for children?', '["Braces for cosmetic reasons", "Standard immunizations", "Private hospital rooms", "Experimental drugs"]', 1, 'Immunizations and regular check-ups are part of the mandatory EPSDT benefit.'),
    (v_topic_id, 'Are Medicaid and CHIP "Continuous" or do they require periodic "Redetermination"?', '["They are for life", "Beneficiaries must have their eligibility re-verified periodically (usually every 12 months)", "They only last for one month", "None of the above"]', 1, 'Redetermination (or "unwinding" post-pandemic) is the process of verifying that a person still qualifies.'),
    (v_topic_id, 'What is the "Woodwork Effect" in Medicaid?', '["Termites in a hospital", "When a policy change (like the ACA) causes people who were ALREADY eligible for Medicaid to finally sign up", "When people hide their income", "The growth of rural clinics"]', 1, 'Publicity around new programs often leads eligible but non-enrolled people to "come out of the woodwork."'),
    (v_topic_id, 'Which federal department oversees Medicaid and CHIP?', '["Department of Labor", "Department of Education", "Department of Health and Human Services (HHS)", "Department of the Treasury"]', 2, 'HHS, via the CMS, oversees these programs.'),
    (v_topic_id, 'What is "Administrative Burden" in the context of Medicaid?', '["The weight of hospital files", "The difficulty and complexity of applying for and maintaining coverage, which can lead to eligible people losing benefits", "The cost of the governor''s office", "None of the above"]', 1, 'High administrative burden is a major barrier to keeping people covered.'),
    (v_topic_id, 'The "Federal Poverty Level" (FPL) is updated how often?', '["Every month", "Every year", "Every 5 years", "Never"]', 1, 'The FPL is updated annually by HHS based on inflation.'),
    (v_topic_id, 'A state''s "Medicaid Plan" is:', '["The map of all hospitals", "A formal contract between the state and federal government describing how the state will run its program", "A list of all doctors in the state", "None of the above"]', 1, 'The State Plan is the governing document for that state''s Medicaid program.'),
    (v_topic_id, 'Under the "Maintenance of Effort" (MOE) requirement, states receiving extra federal funds during a crisis (like COVID-19) are often:', '["Required to build more hospitals", "Prohibited from making their eligibility rules more restrictive or dropping people from coverage", "Required to lower taxes", "Required to hire more doctors"]', 1, 'MOE rules prevent states from cutting their programs while receiving extra federal aid.')
;

END $$;
COMMIT;
